 internal static void Run(){var output=new Audio();using(var sound=new PetSound(()=>new AudioEndpoint{Id="speaker-test",FormFactor=1,WaveId=0},output)){Assert(!sound.Play("hop"),"Headphones mode allowed a speaker");sound.Mode="all";Assert(sound.Play("hop"),"All-output mode blocked speaker");int stops=output.Stops;sound.Mode="headphones";Assert(output.Stops>stops,"Headphones mode did not stop speaker playback");sound.Mode="off";int plays=output.Plays;Assert(!sound.Play("heart")&&output.Plays==plays,"Off mode allowed audio");sound.Mode="all";Assert(sound.PlayRap(new short[100]),"All-output mode blocked rap");sound.Mode="off";}
 string path=Path.Combine(Path.GetTempPath(),"pet-audio-"+Guid.NewGuid().ToString("N")+".txt");using(var pet=new Usagi())try{var sound=(PetSound)Get(pet,"sounds");sound.Mode="all";Set(pet,"preferencesPath",path);Set(pet,"preferencesEnabled",true);Call(pet,"SavePreferences");sound.Mode="off";Call(pet,"LoadPreferences");Assert(sound.Mode=="all","All-output preference not restored");Set(pet,"preferencesEnabled",false);
 using(var form=(Form)Call(pet,"CreateSettingsForm")){form.Show();Application.DoEvents();foreach(Control control in form.Controls)Assert(!control.Text.Contains("음원")&&!control.Text.Contains("변경 내용")&&!control.Text.Contains("확인하지"),"Removed settings item still visible");var selector=(SoundModeControl)form.Controls["SoundMode"];Assert(selector!=null,"Three-way sound selector missing");for(int i=0;i<3;i++){typeof(SoundModeControl).GetMethod("OnMouseDown",f).Invoke(selector,new object[]{new MouseEventArgs(MouseButtons.Left,1,(i*2+1)*selector.Width/6,10,0)});Assert(sound.Mode==new[]{"off","headphones","all"}[i],"Sound selector order incorrect");}sound.Mode="off";
 var title=(LinkLabel)form.Controls["UpdateTitle"];Assert(title!=null&&title.LinkBehavior==LinkBehavior.AlwaysUnderline,"Underlined update title missing");typeof(LinkLabel).GetMethod("OnLinkClicked",f).Invoke(title,new object[]{new LinkLabelLinkClickedEventArgs(title.Links[0])});var page=form.Controls["ReleasePage"];Assert(page!=null&&page.Controls.ContainsKey("UpdatePageAction"),"Update title did not navigate to update page");var notes=(ThemedNotes)page.Controls["ReleaseBody"];string longText="";for(int i=0;i<100;i++)longText+="검증 문서 "+i+" · 스크롤을 내려 끝까지 읽을 수 있어요.\n";notes.Editor.Text=longText;Application.DoEvents();notes.Sync();Assert(notes.Editor.ScrollBars==RichTextBoxScrollBars.None&&notes.Rail.Visible&&notes.LastLine>0,"Themed scrollbar not used");notes.ScrollTo(notes.LastLine);Assert(notes.FirstLine>0,"Themed scrollbar did not move document");notes.ScrollTo(0);Assert(notes.FirstLine==0,"Themed scrollbar did not return to top");SendMessage(notes.Editor.Handle,0x20A,(IntPtr)(-120<<16),IntPtr.Zero);Assert(notes.FirstLine>0,"Mouse wheel over document body did not scroll");notes.ScrollTo(0);typeof(ThemedNotes.NotesRail).GetMethod("OnMouseWheel",f).Invoke(notes.Rail,new object[]{new MouseEventArgs(MouseButtons.None,0,7,30,-120)});Assert(notes.FirstLine>0,"Themed scrollbar wheel did not scroll");typeof(ThemedNotes.NotesRail).GetMethod("OnKeyDown",f).Invoke(notes.Rail,new object[]{new KeyEventArgs(Keys.Home)});Assert(notes.FirstLine==0,"Themed scrollbar Home did not scroll to top");notes.SetMarkdown("# 제목\n\n- 첫 번째 변경 사항입니다.\n- 두 번째 변경 사항입니다.");Assert(notes.Editor.Text.Contains("제목")&&notes.Editor.Text.Contains("첫 번째"),"Formatted notes lost Unicode text");notes.Editor.Select(0,2);Assert(notes.Editor.SelectionFont!=null&&notes.Editor.SelectionFont.Bold,"Notes heading hierarchy missing");using(var image=new Bitmap(notes.Width,notes.Height))notes.DrawToBitmap(image,notes.ClientRectangle);foreach(Control control in page.Controls)if(control.AccessibleName=="뒤로가기"){((SettingButton)control).PerformClick();break;}var previousBounds=form.Bounds;Call(pet,"ShowSettingsInfo",form);var info=(Panel)form.Controls["InfoPage"];Assert(form.Bounds==previousBounds,"Info resized the original settings window");Assert(!info.AutoScroll,"Info page still scrolls");foreach(Control control in Walk(info)){Assert(!(control is ThemedNotes)&&!(control is RichTextBox),"Info page still contains a scroll document");Assert(control.Bottom<=control.Parent.Height,"Info text falls outside panel");if(control.Name=="LicenseNotice")foreach(string line in control.Text.Split('\n'))Assert(control is InfoCopy&&((InfoCopy)control).FitWidth?control.Width/InfoText.Measure(line,control.Font)>=.85f:InfoText.Measure(line,control.Font)<=control.Width,"Info text wraps or compresses excessively");}((SettingButton)info.Controls[0]).PerformClick();Assert(form.Bounds==previousBounds,"Info back navigation did not restore the settings bounds");form.Close();}
 }finally{Set(pet,"preferencesEnabled",false);if(File.Exists(path))File.Delete(path);}Console.WriteLine("PASS: three-way output gating, immediate mute, audio preference, update navigation and themed document scrolling.");}
